using Microsoft.Data.Sqlite;
using System.Text.Json;
var builder = WebApplication.CreateBuilder(args);
builder.WebHost.UseUrls("http://0.0.0.0:3001");
var app = builder.Build();
var root = Environment.GetEnvironmentVariable("DATA_DIR") ?? "/data";
string? Db(string b) => b == "default" ? Path.Combine(root,"kanban.db") : b.Length > 0 && b.All(c => char.IsAsciiLetterOrDigit(c) || c is '-' or '_') ? Path.Combine(root,"kanban","boards",b,"kanban.db") : null;
SqliteConnection? Open(string b) { var p=Db(b); if(p is null || !File.Exists(p)) return null; var c=new SqliteConnection(new SqliteConnectionStringBuilder { DataSource=p, Mode=SqliteOpenMode.ReadOnly }.ToString()); c.Open(); return c; }
List<Dictionary<string,object?>> Q(SqliteConnection c,string sql,params (string,object?)[] args) { using var cmd=c.CreateCommand(); cmd.CommandText=sql; foreach(var (k,v) in args) cmd.Parameters.AddWithValue(k,v??DBNull.Value); using var r=cmd.ExecuteReader(); var rows=new List<Dictionary<string,object?>>(); while(r.Read()) { var row=new Dictionary<string,object?>(); for(int i=0;i<r.FieldCount;i++) row[r.GetName(i)]=r.IsDBNull(i)?null:r.GetValue(i); rows.Add(row); } return rows; }
object? Parse(object? value) { if(value is not string s) return value; try{return JsonSerializer.Deserialize<JsonElement>(s);}catch(JsonException){return s;} }
List<Dictionary<string,object?>> Events(SqliteConnection c,string id,long after,int limit=200) { var rows=Q(c,"SELECT * FROM (SELECT * FROM task_events WHERE task_id=$id AND id>$after ORDER BY id DESC LIMIT $limit) ORDER BY id",("$id",id),("$after",after),("$limit",limit)); foreach(var row in rows) row["payload"]=Parse(row["payload"]); return rows; }
string[] LogTail() { var p=Path.Combine(root,"logs","agent.log"); if(!File.Exists(p)) return []; using var f=new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete); if(f.Length>131072) f.Seek(-131072,SeekOrigin.End); using var r=new StreamReader(f); return r.ReadToEnd().Split('\n').TakeLast(200).Select(x=>x.TrimEnd('\r')).ToArray(); }
IEnumerable<string> Boards() { yield return "default"; var p=Path.Combine(root,"kanban","boards"); if(Directory.Exists(p)) foreach(var d in Directory.EnumerateDirectories(p)) yield return Path.GetFileName(d); }
var statuses=new[]{"triage","todo","ready","scheduled","running","blocked","review","done"};
app.MapGet("/api/boards",()=> { var result=new List<object>(); foreach(var b in Boards()) { using var c=Open(b); if(c is null) continue; var counts=statuses.ToDictionary(x=>x,_=>0); foreach(var r in Q(c,"SELECT status,COUNT(*) AS n FROM tasks GROUP BY status")) counts[(string)r["status"]!]=Convert.ToInt32(r["n"]); result.Add(new {id=b,name=b,path=Db(b),counts}); } return Results.Json(result); });
app.MapGet("/api/boards/{board}/tasks",(string board)=> { using var c=Open(board); if(c is null) return Results.NotFound(); var groups=statuses.ToDictionary(x=>x,_=>new List<Dictionary<string,object?>>()); foreach(var row in Q(c,"SELECT * FROM tasks ORDER BY created_at DESC")) { var status=(string)row["status"]!; if(!groups.ContainsKey(status)) groups[status]=[]; groups[status].Add(row); } return Results.Json(groups); });
app.MapGet("/api/tasks/{board}/{taskId}",(string board,string taskId)=> { using var c=Open(board); if(c is null) return Results.NotFound(); var task=Q(c,"SELECT * FROM tasks WHERE id=$id",("$id",taskId)).FirstOrDefault(); return task is null ? Results.NotFound() : Results.Json(new {task,runs=Q(c,"SELECT * FROM task_runs WHERE task_id=$id ORDER BY id DESC",("$id",taskId)),comments=Q(c,"SELECT * FROM task_comments WHERE task_id=$id ORDER BY id",("$id",taskId))}); });
app.MapGet("/api/tasks/{board}/{taskId}/console",(string board,string taskId)=> { using var c=Open(board); return c is null || Q(c,"SELECT id FROM tasks WHERE id=$id",("$id",taskId)).Count==0 ? Results.NotFound() : Results.Json(new {events=Events(c,taskId,0),log=LogTail()}); });
app.MapGet("/api/profiles",()=> { var profiles=new HashSet<string>(); foreach(var b in Boards()) { using var c=Open(b); if(c is not null) foreach(var r in Q(c,"SELECT DISTINCT assignee FROM tasks WHERE assignee IS NOT NULL AND assignee!=''")) profiles.Add((string)r["assignee"]!); } var p=Path.Combine(root,"profiles"); if(Directory.Exists(p)) foreach(var d in Directory.EnumerateDirectories(p)) profiles.Add(Path.GetFileName(d)); return Results.Json(profiles.OrderBy(x=>x)); });
app.MapPost("/api/tasks",(NewTask input)=> { if(input.Board is not null && input.Board!="default") return Results.BadRequest(new {error="Only default board is writable"}); if(string.IsNullOrWhiteSpace(input.Title)) return Results.BadRequest(new {error="title required"}); var p=Db("default")!; if(!File.Exists(p)) return Results.NotFound(); using var c=new SqliteConnection(new SqliteConnectionStringBuilder {DataSource=p,Mode=SqliteOpenMode.ReadWrite,DefaultTimeout=5}.ToString()); c.Open(); using(var timeout=c.CreateCommand()) {timeout.CommandText="PRAGMA busy_timeout=5000";timeout.ExecuteNonQuery();} using var tx=c.BeginTransaction(); var id=Guid.NewGuid().ToString("N"); using var cmd=c.CreateCommand(); cmd.Transaction=tx; cmd.CommandText="INSERT INTO tasks (id,title,body,assignee,priority,status,tenant,created_by,workspace_kind,created_at) VALUES ($id,$title,$body,$assignee,$priority,'todo',NULL,'kanban-console','scratch',$created)"; cmd.Parameters.AddWithValue("$id",id); cmd.Parameters.AddWithValue("$title",input.Title.Trim()); cmd.Parameters.AddWithValue("$body",(object?)input.Body??DBNull.Value); cmd.Parameters.AddWithValue("$assignee",(object?)input.Assignee??DBNull.Value); cmd.Parameters.AddWithValue("$priority",input.Priority??0); cmd.Parameters.AddWithValue("$created",DateTimeOffset.UtcNow.ToUnixTimeSeconds()); cmd.ExecuteNonQuery(); tx.Commit(); return Results.Json(new{id},statusCode:201); });
app.MapGet("/api/stream/{board}/{taskId}",async(string board,string taskId,HttpContext ctx)=> { using(var c=Open(board)) {if(c is null || Q(c,"SELECT id FROM tasks WHERE id=$id",("$id",taskId)).Count==0) {ctx.Response.StatusCode=404;return;}} ctx.Response.Headers.ContentType="text/event-stream"; ctx.Response.Headers.CacheControl="no-cache"; var last=0L; var log=Path.Combine(root,"logs","agent.log"); long pos=File.Exists(log)?new FileInfo(log).Length:0; string partial=""; var token=ctx.RequestAborted; try {while(!token.IsCancellationRequested) {using(var c=Open(board)) if(c is not null) foreach(var e in Events(c,taskId,last,1000)) {last=Convert.ToInt64(e["id"]); await ctx.Response.WriteAsync($"id: {last}\nevent: event\ndata: {JsonSerializer.Serialize(e)}\n\n",token);} if(File.Exists(log)) {using var f=new FileStream(log,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete); if(f.Length<pos) {pos=0;partial="";} f.Position=pos; using var r=new StreamReader(f); var text=await r.ReadToEndAsync(token); pos=f.Position; var lines=(partial+text).Split('\n'); partial=lines[^1]; foreach(var line in lines.SkipLast(1)) await ctx.Response.WriteAsync($"event: log\ndata: {JsonSerializer.Serialize(line.TrimEnd('\r'))}\n\n",token);} await ctx.Response.WriteAsync(": heartbeat\n\n",token); await ctx.Response.Body.FlushAsync(token); await Task.Delay(1000,token);}}catch(OperationCanceledException) when(token.IsCancellationRequested){} });
app.Run();
record NewTask(string? Board,string Title,string? Body,string? Assignee,int? Priority);
